const SK = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6InR3dGhnYXBpb3VpcWhhdnJjbnJ5Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc3NDUzMTY3NiwiZXhwIjoyMDkwMTA3Njc2fQ.EyNdtvECdcHx3RuaizdfLGNRY4OJotzjE2QeOQ9Yf4Q';
const SUPA = 'https://twthgapiouiqhavrcnry.supabase.co';
const h = { apikey: SK, Authorization: `Bearer ${SK}` };
const {execSync} = require('child_process');

// Get KAOS open issues
const mainRes = await fetch(`${SUPA}/rest/v1/issues?assignee=eq.main&status=eq.open&acceptance_criteria=not.is.null&description=not.is.null&order=priority.asc&limit=5&select=id,task_key,title,project,description,acceptance_criteria,type,sprint`, {headers:h});
const mainIssues = await mainRes.json();

// Check DoF-ready features per project
const featRes = await fetch(`${SUPA}/rest/v1/issues?type=eq.feature&status=eq.open&select=id,project`, {headers:h});
const features = await featRes.json();
const withChildren = [];
for (const f of features) {
  const cr = await fetch(`${SUPA}/rest/v1/issues?parent_id=eq.${f.id}&select=id&limit=1`, {headers:h});
  const c = await cr.json();
  if (c.length > 0) withChildren.push(f.project);
}
const byProject = {};
withChildren.forEach(p => byProject[p] = (byProject[p]||0)+1);
const gaps = ['Vespera','Mission Control','Infrastructure'].filter(p => (byProject[p]||0) < 3);

if (!mainIssues.length && !gaps.length) return [{json:{action:'idle'}}];

const doList = mainIssues.map(i=>`[${i.task_key}] ${i.project}: ${i.title}`).join('\n');
const gapText = gaps.length ? `\nProjects needing DoF-ready features (< 3): ${gaps.join(', ')}` : '';

const prompt = [
  'You are KAOS orchestrator. Work through your open issues.',
  '',
  'Your open issues:',
  doList || '(none)',
  gapText,
  '',
  'For each issue: read description+AC, implement or delegate, mark done via MC API PATCH http://localhost:3000/api/issues',
  'For feature gaps: find a backlog feature, create 2-4 child tasks, PATCH feature status=open',
  'Supabase: ' + SUPA + ' apikey: ' + SK
].join('\n').replace(/'/g, "'\\''");

try {
  execSync(`openclaw agent run main --message '${prompt}' 2>/dev/null`, {timeout:600000});
} catch(e) {}

return [{json:{action:'kaos_spawned', issues: mainIssues.map(i=>i.task_key), gaps}}];
